import { renderHook, act } from '@testing-library/react';
import { AppProvider, useApp } from './AppContext';
import { AppState, Activity } from '@/types';

// Mock localStorage
const localStorageMock = {
  getItem: vi.fn(),
  setItem: vi.fn(),
  removeItem: vi.fn(),
  clear: vi.fn()
};
Object.defineProperty(window, 'localStorage', {
  value: localStorageMock
});

describe('AppContext', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('initialisiert den Context', () => {
    const { result } = renderHook(() => useApp(), {
      wrapper: AppProvider
    });

    expect(result.current.appState).toBeDefined();
    expect(typeof result.current.addActivity).toBe('function');
    expect(typeof result.current.toggleActivityStatus).toBe('function');
  });

  it('kann Aktivitäten hinzufügen', () => {
    const { result } = renderHook(() => useApp(), {
      wrapper: AppProvider
    });

    const activity: Omit<Activity, 'id' | 'createdAt' | 'updatedAt'> = {
      name: 'Test Activity',
      category: 'Work',
      description: 'Test',
      dailyTarget: 10
    };

    act(() => {
      result.current.addActivity(activity);
    });

    expect(localStorageMock.setItem).toHaveBeenCalled();
    // Aktivität wurde hinzugefügt
    expect(result.current.appState.activities.length).toBe(1);
  });

  it('kann Aktivitäten aktualisieren', () => {
    // Zuerst Aktivität hinzufügen
    const { result } = renderHook(() => useApp(), {
      wrapper: AppProvider
    });

    let activityId: string;
    act(() => {
      result.current.addActivity({
        name: 'Test Activity',
        category: 'Work',
        description: 'Test',
        dailyTarget: 10
      });
      activityId = result.current.appState.activities[0].id;
    });

    // Aktivität aktualisieren
    act(() => {
      result.current.updateActivity(activityId, { name: 'Updated Activity' });
    });

    expect(localStorageMock.setItem).toHaveBeenCalled();
    expect(result.current.appState.activities[0].name).toBe('Updated Activity');
  });

  it('kann Aktivitäten löschen', () => {
    const { result } = renderHook(() => useApp(), {
      wrapper: AppProvider
    });

    let activityId: string;
    act(() => {
      result.current.addActivity({
        name: 'Test Activity',
        category: 'Work',
        description: 'Test',
        dailyTarget: 10
      });
      activityId = result.current.appState.activities[0].id;
    });

    act(() => {
      result.current.deleteActivity(activityId);
    });

    expect(localStorageMock.setItem).toHaveBeenCalled();
    expect(result.current.appState.activities.length).toBe(0);
  });

  it('kann Datum ändern', () => {
    const { result } = renderHook(() => useApp(), {
      wrapper: AppProvider
    });

    act(() => {
      result.current.changeDate('2026-10-01');
    });

    expect(result.current.appState.currentViewDate).toBe('2026-10-01');
  });

  it('kann zum aktuellen Tag springen', () => {
    const { result } = renderHook(() => useApp(), {
      wrapper: AppProvider
    });

    act(() => {
      result.current.changeDate('2026-10-01');
    });

    act(() => {
      result.current.goToday();
    });

    const today = new Date().toISOString().split('T')[0];
    expect(result.current.appState.currentViewDate).toBe(today);
  });

  it('kann Theme umschalten', () => {
    const { result } = renderHook(() => useApp(), {
      wrapper: AppProvider
    });

    act(() => {
      result.current.toggleTheme();
    });

    expect(localStorageMock.setItem).toHaveBeenCalledWith('pulseboard_theme', 'dark');
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { 
  getInitialAppState, 
  validateVersion, 
  loadAppState, 
  saveAppState, 
  clearStorage,
  formatDisplayDate,
  isFutureDate,
  isPastDate
} from './storage';
import { AppState, VersionedData, VERSIONED_DATA_VERSION, STORAGE_KEY } from '@/types';

// Mock localStorage
const localStorageMock = {
  getItem: vi.fn(),
  setItem: vi.fn(),
  removeItem: vi.fn(),
  clear: vi.fn()
};
Object.defineProperty(window, 'localStorage', {
  value: localStorageMock
});

describe('storage utils', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('getInitialAppState', () => {
    it('gibt initialen AppState zurück', () => {
      const state = getInitialAppState();
      expect(state.activities).toEqual([]);
      expect(state.dailyStatuses).toEqual([]);
      expect(state.currentViewDate).toBeDefined();
    });

    it('hat heute als Standarddatum', () => {
      const state = getInitialAppState();
      const today = new Date().toISOString().split('T')[0];
      expect(state.currentViewDate).toBe(today);
    });
  });

  describe('validateVersion', () => {
    it('validiert korrekte Datenstruktur', () => {
      const data: VersionedData = {
        version: VERSIONED_DATA_VERSION,
        data: getInitialAppState()
      };
      expect(validateVersion(data)).toBe(true);
    });

    it('validiert falsche Version', () => {
      const data = {
        version: 999,
        data: getInitialAppState()
      };
      expect(validateVersion(data)).toBe(false);
    });

    it('validiert falsche Datenstruktur', () => {
      const data = {
        version: VERSIONED_DATA_VERSION,
        data: {
          activities: 'not an array',
          dailyStatuses: [],
          currentViewDate: '2026-09-23'
        }
      };
      expect(validateVersion(data)).toBe(false);
    });

    it('validiert fehlende Felder', () => {
      const data = {
        version: VERSIONED_DATA_VERSION,
        data: {
          activities: [],
          dailyStatuses: []
          // currentViewDate fehlt
        }
      };
      expect(validateVersion(data)).toBe(false);
    });
  });

  describe('loadAppState', () => {
    it('gibt initialen AppState zurück wenn nichts gespeichert ist', () => {
      localStorageMock.getItem.mockReturnValue(null);
      const state = loadAppState();
      expect(state.activities).toEqual([]);
    });

    it('gibt gespeicherte Daten zurück', () => {
      const state: AppState = {
        activities: [{ id: '1', name: 'Test', category: 'Work', createdAt: new Date().toISOString() }],
        dailyStatuses: [],
        currentViewDate: '2026-09-23'
      };
      const data: VersionedData = {
        version: VERSIONED_DATA_VERSION,
        data: state
      };
      localStorageMock.getItem.mockReturnValue(JSON.stringify(data));

      const loaded = loadAppState();
      expect(loaded.activities.length).toBe(1);
    });

    it('gibt initialen AppState zurück bei beschädigten Daten', () => {
      localStorageMock.getItem.mockReturnValue('not json');
      const state = loadAppState();
      expect(state.activities).toEqual([]);
    });
  });

  describe('saveAppState', () => {
    it('speichert AppState mit Version', () => {
      const state: AppState = getInitialAppState();
      saveAppState(state);

      expect(localStorageMock.setItem).toHaveBeenCalled();
      const call = localStorageMock.setItem.mock.calls[0];
      const savedData = JSON.parse(call[1]);
      expect(savedData.version).toBe(VERSIONED_DATA_VERSION);
    });
  });

  describe('clearStorage', () => {
    it('löscht Storage', () => {
      clearStorage();
      expect(localStorageMock.removeItem).toHaveBeenCalledWith(STORAGE_KEY);
    });
  });

  describe('formatDisplayDate', () => {
    it('formatiert ein Datum', () => {
      const formatted = formatDisplayDate('2026-09-23');
      expect(formatted).toContain('2026');
    });

    it('gibt Originalstring zurück bei ungültigem Datum', () => {
      expect(formatDisplayDate('invalid')).toBe('invalid');
    });
  });

  describe('isFutureDate', () => {
    it('erkent Zukunft', () => {
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      const tomorrowStr = tomorrow.toISOString().split('T')[0];
      expect(isFutureDate(tomorrowStr)).toBe(true);
    });

    it('erkent Vergangenheit', () => {
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      const yesterdayStr = yesterday.toISOString().split('T')[0];
      expect(isFutureDate(yesterdayStr)).toBe(false);
    });

    it('erkent heute nicht als Zukunft', () => {
      const today = new Date().toISOString().split('T')[0];
      expect(isFutureDate(today)).toBe(false);
    });
  });

  describe('isPastDate', () => {
    it('erkent Vergangenheit', () => {
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      const yesterdayStr = yesterday.toISOString().split('T')[0];
      expect(isPastDate(yesterdayStr)).toBe(true);
    });

    it('erkent Zukunft nicht als Vergangenheit', () => {
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      const tomorrowStr = tomorrow.toISOString().split('T')[0];
      expect(isPastDate(tomorrowStr)).toBe(false);
    });

    it('erkent heute nicht als Vergangenheit', () => {
      const today = new Date().toISOString().split('T')[0];
      expect(isPastDate(today)).toBe(false);
    });
  });
});

