/**
 * Hook für state management mit persistence
 */
export function useStorageState(initialValue?: AppState): [AppState, (state: Partial<AppState> | ((prev: AppState) => Partial<AppState>)) => void] {
  const [appState, setAppState] = useState<AppState>(() => {
    if (initialValue) {
      return initialValue;
    }

    try {
      return loadAppState();
    } catch (error) {
      console.error('Error loading initial state:', error);
      return getInitialAppState();
    }
  });

  const updateState = useCallback((partial: Partial<AppState> | ((prev: AppState) => Partial<AppState>)) => {
    setAppState(prev => {
      const stateUpdate = typeof partial === 'function' ? partial(prev) : partial;
      const newState = { ...prev, ...stateUpdate };
      try {
        saveAppState(newState);
      } catch (error) {
        console.error('Error saving state:', error);
      }
      return newState;
    });
  }, []);

