export function useStorageActivity(activityId: string | null): [Activity | undefined, (updates: Partial<Activity>) => void] {
  const [appState, updateAppState] = useStorageState();

  const activity = appState.activities.find(a => a.id === activityId);

  const updateActivity = useCallback((updates: Partial<Activity>) => {
    if (!activityId) return;

    updateAppState({
      activities: appState.activities.map(a => {
        if (a.id === activityId) {
          return { ...a, ...updates };
        }
        return a;
      })
    });
  }, [activityId, appState.activities, updateAppState]);

