104:  * Speichert den aktuellen AppState
105:  */
106: export function saveAppState(appState: AppState): void {
107:   try {
108:     const data: VersionedData = {
109:       version: VERSIONED_DATA_VERSION,
110:       data: appState
111:     };
112:     
113:     localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
114:   } catch (error) {
