131: /**
132:  * Iteriert über alle Tage in einem Bereich
133:  */
134: export function getDaysInRange(startDate: Date, endDate: Date): string[] {
135:   const days: string[] = [];
136:   const current = new Date(startDate);
137:   
138:   while (current <= endDate) {
139:     days.push(current.toISOString().split('T')[0]);
140:     current.setDate(current.getDate() + 1);
141:   }
142:   
143:   return days;
144: }
